using System.Text.Json;
using FBS.Student.Native;
internal static class Program
{
 [STAThread]private static void Main(){int passed=0;void Check(bool ok,string name){if(!ok)throw new Exception("FAIL: "+name);passed++;Console.WriteLine("PASS: "+name);}
 Application.EnableVisualStyles();using var form=new Form{Text="FBS owned appearance fixture",ClientSize=new Size(340,422)};int settings=0,stop=0;using var dashboard=new StudentDashboard(()=>settings++,()=>stop++,()=>{},()=>{});form.Controls.Add(dashboard);
 form.Shown+=(_,_)=>{try{using(var d=JsonDocument.Parse("{\"connected\":false,\"approved\":true,\"deviceId\":\"PC-07\"}")){dashboard.ApplyConnection(d.RootElement);Check(dashboard.DisplayedConnection.Contains("غير متصل"),"approval without a live connection cannot be green");}using(var d=JsonDocument.Parse("{\"connected\":true,\"approved\":false}")){dashboard.ApplyConnection(d.RootElement);Check(dashboard.DisplayedConnection.Contains("بانتظار"),"unapproved live student shows pending approval");}using(var d=JsonDocument.Parse("{\"connected\":true,\"approved\":true,\"deviceId\":\"PC-07\",\"labName\":\"معمل ويندوز 11\"}")){dashboard.ApplyConnection(d.RootElement);Check(dashboard.DisplayedConnection.Contains("✓"),"approved live student shows connected banner");}
 Check(dashboard.Bounds==form.ClientRectangle,"student dashboard fills compact native window");Check(dashboard.Controls.OfType<Label>().Any(x=>x.Text=="اسم الجهاز: PC-07"),"actual device identifier is rendered");Check(dashboard.Controls.OfType<Label>().Any(x=>x.Text=="المعمل: معمل ويندوز 11"),"actual lab name is rendered");dashboard.Controls.OfType<Button>().Single(x=>x.Text.Contains("الإعدادات")).PerformClick();Check(settings==1,"settings affordance remains functional");dashboard.Controls.OfType<Button>().Single(x=>x.Text.Contains("إيقاف")).PerformClick();Check(stop==1,"local stop remains functional");Directory.CreateDirectory("checks-output");using(var bitmap=new Bitmap(dashboard.Width,dashboard.Height)){dashboard.DrawToBitmap(bitmap,dashboard.ClientRectangle);bitmap.Save("checks-output/Student-M183-Windows.png",System.Drawing.Imaging.ImageFormat.Png);}dashboard.SetDisconnected();Check(!dashboard.DisplayedConnection.Contains("✓"),"connection loss removes connected banner");Console.WriteLine($"Appearance checks: {passed} passed. Rendered fixture data, not a user computer.");}
 catch(Exception ex){Console.Error.WriteLine("FAIL: "+ex.Message);Environment.ExitCode=1;}finally{form.Close();}};Application.Run(form);}
}
